using VMLAssembler;

namespace VMLTranslators
{
    /// <summary>
    /// 8051 转译器
    /// </summary>
    public class Translator8051 : Translator8bit
    {
        public override string ARCH_NAME => "8051";
        protected override string CallMnemonic => "LCALL";

        // 8051 中断上下文
        protected override string[] ContextRegNames() => new[] { "ACC", "B", "DPH", "DPL", "PSW" };
        protected override string NativeIret() => "reti";
        protected override string NativeCli() => "clr EA";
        protected override string NativeSti() => "setb EA";
        protected override void EmitNativeInt(int vector)
        {
            Emit($"        MOV A, #{vector}");
            Emit("        LCALL INT_HANDLER");
        }
        protected override void EmitSaveContext()
        {
            foreach (var r in ContextRegNames())
                Emit($"        PUSH {r}");
        }
        protected override void EmitRestoreContext()
        {
            var regs = ContextRegNames();
            for (int i = regs.Length - 1; i >= 0; i--)
                Emit($"        POP {regs[i]}");
        }

        private readonly Dictionary<int, string> REGISTER_MAP = new Dictionary<int, string>
        {
            { 0, "A" },
            { 1, "B" },
            { 2, "R0" },
            { 3, "R1" },
            { 4, "R2" },
            { 5, "R3" },
            { 6, "R4" },
            { 7, "R5" }
        };

        // VML 是32位指令集，8051 是8位架构
        // 虚拟寄存器映射到内部RAM：R0-R15 每个占4字节
        // 使用间接寻址方式访问：R0=#VR_BASE, R1作为偏移
        private const string VR_BASE = "30H";  // 虚拟寄存器起始地址（内部RAM）

        // 获取虚拟寄存器的内存偏移
        private string GetRegOffset(int regNum) => $"{regNum * 4:X2}H";

        public Translator8051(VmlProgram vmlProgram) : base(vmlProgram) { }

        protected override void EmitHeader()
        {
            Emit("; 8051 Assembly - Translated from VML");
            Emit("; Generated by VML Translator");
            Emit("");
            Emit("        $MOD51");
            Emit("");
        }

        protected override void EmitDataSection()
        {
            if (VmlProgram.DataSection.Count > 0)
            {
                Emit("");
                Emit("        DSEG");
                foreach (var kvp in VmlProgram.DataSection)
                {
                    string name = kvp.Key;
                    object value = kvp.Value;

                    if (int.TryParse(value.ToString(), out _))
                    {
                        Emit($"{name} DS 1");
                    }
                }
            }
        }

        protected override void EmitCode()
        {
            Emit("");
            Emit("        CSEG");
            Emit("        ORG 0000H");
            Emit("");

            foreach (var instr in VmlProgram.Instructions)
            {
                if (!string.IsNullOrEmpty(instr.Label))
                {
                    Emit($"{instr.Label}:");
                }
                NormalizeAndTranslate(instr);
            }
        }

        protected override void TranslateInstruction(Instruction instr)
        {
            // NormalizeBinaryOp handled by BaseTranslator.NormalizeAndTranslate
            switch (instr.Opcode)
            {
                                                case OpCode.ADD:
                    TranslateAdd(instr);
                    break;
                case OpCode.SUB:
                    TranslateSub(instr);
                    break;
                case OpCode.MOVE:
                    TranslateMove(instr);
                    break;
                case OpCode.CMP:
                    TranslateCmp(instr);
                    break;
                case OpCode.JMP:
                    Emit($"        SJMP {instr.Operands[0].Value}");
                    break;
                case OpCode.JZ:
                    Emit($"        JZ {instr.Operands[0].Value}");
                    break;
                case OpCode.JNZ:
                    Emit($"        JNZ {instr.Operands[0].Value}");
                    break;
                case OpCode.HALT:
                    Emit("        SJMP $");
                    break;
                case OpCode.NOP:
                    Emit("        NOP");
                    break;
                case OpCode.STI:
                // CLI/STI/INT/IRET handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.THROW:
                    Emit($"        MOV A, #{instr.Operands[0].Value}");
                    Emit("        LCALL EXCEPTION_HANDLER");
                    break;
                case OpCode.CATCH:
                    Emit($"        ; Set interrupt handler: {instr.Operands[0].Value}");
                    Emit("        ; Modify vector table at assembly time");
                    break;
                case OpCode.ENDCATCH:
                    break;

                // 浮点运算指令 (8051 无硬件浮点，使用软浮点库)
                case OpCode.FADD:
                    Emit("        ; FADD - 谯用软浮点加法库");
                    Emit("        LCALL FP_ADD");
                    break;
                case OpCode.FSUB:
                    Emit("        ; FSUB - 谯用软浮点减法库");
                    Emit("        LCALL FP_SUB");
                    break;
                case OpCode.FMUL:
                    Emit("        ; FMUL - 谯用软浮点乘法库");
                    Emit("        LCALL FP_MUL");
                    break;
                case OpCode.FDIV:
                    Emit("        ; FDIV - 谯用软浮点除法库");
                    Emit("        LCALL FP_DIV");
                    break;
                case OpCode.FNEG:
                    Emit("        ; FNEG - 符号位取反");
                    Emit("        XRL FP_SIGN, #80H");
                    break;
                case OpCode.FCMP:
                    Emit("        ; FCMP - 谯用软浮点比较库");
                    Emit("        LCALL FP_CMP");
                    break;

                // 浮点类型转换
                case OpCode.I2F:
                    Emit("        LCALL FP_I2F");
                    break;
                case OpCode.F2I:
                    Emit("        LCALL FP_F2I");
                    break;
                case OpCode.F2D:
                    Emit("        ; 单精度转双精度");
                    Emit("        LCALL FP_EXTEND");
                    break;
                case OpCode.D2F:
                    Emit("        ; 双精度转单精度");
                    Emit("        LCALL FP_TRUNC");
                    break;

                // 浮点数据传输
                case OpCode.MOVEF:
                                // MOVEF store path: dest != REGISTER → FSTORE (handled via goto from MOVEF above)
                                case OpCode.FPUSH:
                    Emit("        LCALL FP_PUSH");
                    break;
                case OpCode.FPOP:
                    Emit("        LCALL FP_POP");
                    break;

                // 算术指令
                case OpCode.MUL:
                    Emit("        ; MUL - 8051 无硬件乘法，用 LCALL MUL32");
                    Emit("        LCALL MUL32");
                    break;
                case OpCode.DIV:
                    Emit("        ; DIV - 8051 无硬件除法，用 LCALL DIV32");
                    Emit("        LCALL DIV32");
                    break;
                case OpCode.MOD:
                    Emit("        ; MOD - 8051 无硬件模除，用 LCALL MOD32");
                    Emit("        LCALL MOD32");
                    break;
                case OpCode.INC:
                    Emit($"        INC {instr.Operands[0].Value}");
                    break;
                case OpCode.DEC:
                    Emit($"        DEC {instr.Operands[0].Value}");
                    break;
                case OpCode.NEG:
                    Emit($"        ; NEG R");
                    Emit($"        MOV A, {instr.Operands[0].Value}");
                    Emit("        CPL A");
                    Emit("        INC A");
                    Emit($"        MOV {instr.Operands[0].Value}, A");
                    break;

                // 逻辑指令
                case OpCode.AND:
                    Emit("        LCALL AND32");
                    break;
                case OpCode.OR:
                    Emit("        LCALL OR32");
                    break;
                case OpCode.XOR:
                    Emit("        LCALL XOR32");
                    break;
                case OpCode.NOT:
                    Emit($"        MOV A, {instr.Operands[0].Value}");
                    Emit("        CPL A");
                    Emit($"        MOV {instr.Operands[0].Value}, A");
                    break;
                case OpCode.TEST:
                    Emit("        ; TEST - ANL A, #0 比较零标志");
                    Emit("        MOV A, R0");
                    Emit("        JZ TEST_Z");
                    Emit("        SJMP TEST_NZ");
                    Emit("TEST_Z:");
                    Emit("        ; Zero flag set");
                    Emit("TEST_NZ:");
                    break;

                // 位移指令
                case OpCode.SHL:
                    Emit("        ; SHL - 左移 R0");
                    Emit("        MOV A, R0");
                    Emit("        MOV C, ACC.7");
                    Emit("        RL A");
                    Emit("        MOV R0, A");
                    Emit("        ; 进位标志在 C");
                    break;
                case OpCode.SHR:
                    Emit("        ; SHR - 右移 R0");
                    Emit("        MOV A, R0");
                    Emit("        MOV C, ACC.0");
                    Emit("        RR A");
                    Emit("        MOV R0, A");
                    Emit("        ; 进位标志在 C");
                    break;

                // 栈和函数调用指令
                case OpCode.PUSH:
                    Emit($"        PUSH {instr.Operands[0].Value}");
                    break;
                case OpCode.POP:
                    Emit($"        POP {instr.Operands[0].Value}");
                    break;
                case OpCode.CALL:
                    Emit($"        LCALL {instr.Operands[0].Value}");
                    break;
                case OpCode.RET:
                    Emit("        RET");
                    break;
                // case OpCode.RET_VAL:
                //     Emit("        ; RET_VAL - 返回值已在 R0");
                //     Emit("        RET");
                //     break;

                // 标签指令
                case OpCode.LABEL:
                    Emit($"{instr.Operands[0].Value}:");
                    break;

                // 比较跳转指令
                case OpCode.JE:
                    Emit($"        ; JE - R0 == R1 则跳转");
                    Emit("        MOV A, R0");
                    Emit("        CLR C");
                    Emit("        SUBB A, R1");
                    Emit($"        JZ {instr.Operands[0].Value}");
                    break;
                case OpCode.JNE:
                    Emit($"        ; JNE - R0 != R1 则跳转");
                    Emit("        MOV A, R0");
                    Emit("        CLR C");
                    Emit("        SUBB A, R1");
                    Emit($"        JNZ {instr.Operands[0].Value}");
                    break;
                case OpCode.JL:
                    Emit($"        ; JL - R0 < R1 则跳转");
                    Emit("        MOV A, R0");
                    Emit("        CLR C");
                    Emit("        SUBB A, R1");
                    Emit($"        JC {instr.Operands[0].Value}");
                    break;
                case OpCode.JLE:
                    Emit($"        ; JLE - R0 <= R1 则跳转");
                    Emit("        MOV A, R0");
                    Emit("        CLR C");
                    Emit("        SUBB A, R1");
                    Emit($"        JZ {instr.Operands[0].Value}");
                    Emit($"        JC {instr.Operands[0].Value}");
                    break;
                case OpCode.JG:
                    Emit($"        ; JG - R0 > R1 则跳转");
                    Emit("        MOV A, R0");
                    Emit("        CLR C");
                    Emit("        SUBB A, R1");
                    Emit($"        JNC {instr.Operands[0].Value}");
                    Emit($"        JZ SKIP{instr.Operands[0].Value}");
                    Emit($"SKIP{instr.Operands[0].Value}:");
                    break;
                case OpCode.JGE:
                    Emit($"        ; JGE - R0 >= R1 则跳转");
                    Emit("        MOV A, R0");
                    Emit("        CLR C");
                    Emit("        SUBB A, R1");
                    Emit($"        JNC {instr.Operands[0].Value}");
                    break;

                // 内存管理指令 (VML 中 ALLOC/FREE 通过 SYSCALL 40/41 实现)
                case OpCode.SYSCALL:
                    Emit($"        ; SYSCALL {instr.Operands[0].Value}");
                    Emit("        LCALL SYSCALL_HANDLER");
                    break;


                // 栈帧管理
                case OpCode.ENTER:
                    {
                        int size = int.Parse(instr.Operands[0].Value.ToString());
                        Emit("        ; ENTER: PUSH BP; MOVE BP,SP; SUB SP,size");
                        Emit("        PUSH DPH");
                        Emit("        PUSH DPL");
                        if (size > 0)
                            Emit($"        ; SUB SP, #{size}");
                    }
                    break;
                case OpCode.LEAVE:
                    Emit("        ; LEAVE: MOVE SP,BP; POP BP");
                    Emit("        POP DPL");
                    Emit("        POP DPH");
                    break;

                // 标志位控制
                case OpCode.CLC:
                    Emit("        CLR C");
                    break;
                case OpCode.STC:
                    Emit("        SETB C");
                    break;

                // 内联汇编
                // OpCode.ASM handled by BaseTranslator.TryTranslateCommonOpcode
                // OpCode.CHIPASM handled by BaseTranslator.TryTranslateCommonOpcode

                // 地址计算
                                // 8位数据传输
                                                                                case OpCode.MOVEB:
                    {
                        var dst = instr.Operands[0];
                        var src = instr.Operands[1];
                        if (dst.Type == OperandType.REGISTER && src.Type == OperandType.REGISTER)
                        {
                            int dstReg = (int)dst.Value;
                            int srcReg = (int)src.Value;
                            string dstOffset = GetRegOffset(dstReg);
                            string srcOffset = GetRegOffset(srcReg);
                            Emit($"        ; MOVEB R{dstReg}, R{srcReg} (8-bit)");
                            Emit("        PUSH 00H");
                            Emit("        PUSH 01H");
                            Emit($"        MOV DPTR, #{VR_BASE}");
                            Emit($"        MOV A, #{srcOffset}");
                            Emit("        MOVC A, @A+DPTR");
                            Emit("        MOV R1, A");
                            Emit($"        MOV DPTR, #{VR_BASE}");
                            Emit($"        MOV A, #{dstOffset}");
                            Emit("        MOVC A, @A+DPTR");
                            Emit("        MOV @R1, A");
                            Emit("        POP 01H");
                            Emit("        POP 00H");
                        }
                    }
                    break;
                case OpCode.MOVEH:
                    {
                        var dst = instr.Operands[0];
                        var src = instr.Operands[1];
                        if (dst.Type == OperandType.REGISTER && src.Type == OperandType.REGISTER)
                        {
                            int dstReg = (int)dst.Value;
                            int srcReg = (int)src.Value;
                            string dstOffset = GetRegOffset(dstReg);
                            string srcOffset = GetRegOffset(srcReg);
                            Emit($"        ; MOVEW R{dstReg}, R{srcReg} (16-bit)");
                            Emit("        PUSH 00H");
                            Emit("        PUSH 01H");
                            Emit("        ; copy 2 bytes from src to dst");
                            Emit($"        MOV DPTR, #{VR_BASE}");
                            Emit($"        MOV A, #{srcOffset}");
                            Emit("        MOVC A, @A+DPTR");
                            Emit("        MOV R1, A");
                            Emit("        INC DPTR");
                            Emit("        CLR A");
                            Emit($"        MOV A, #{srcOffset}");
                            Emit("        INC A");
                            Emit("        MOVC A, @A+DPTR");
                            Emit("        MOV R0, A");
                            Emit("        POP 01H");
                            Emit("        POP 00H");
                        }
                    }
                    break;
                case OpCode.PUSHB:
                    {
                        var src = instr.Operands[0];
                        if (src.Type == OperandType.REGISTER)
                        {
                            int regNum = (int)src.Value;
                            string offset = GetRegOffset(regNum);
                            Emit($"        ; PUSHB R{regNum} (8-bit)");
                            Emit($"        MOV DPTR, #{VR_BASE}");
                            Emit($"        MOV A, #{offset}");
                            Emit("        MOVC A, @A+DPTR");
                            Emit("        PUSH ACC");
                        }
                    }
                    break;
                case OpCode.PUSHH:
                    {
                        var src = instr.Operands[0];
                        if (src.Type == OperandType.REGISTER)
                        {
                            int regNum = (int)src.Value;
                            string offset = GetRegOffset(regNum);
                            Emit($"        ; PUSHW R{regNum} (16-bit)");
                            Emit("        PUSH 00H");
                            Emit("        PUSH 01H");
                            Emit($"        MOV DPTR, #{VR_BASE}");
                            Emit($"        MOV A, #{offset}");
                            Emit("        MOVC A, @A+DPTR");
                            Emit("        MOV R1, A");
                            Emit("        INC DPTR");
                            Emit("        CLR A");
                            Emit($"        MOV A, #{offset}");
                            Emit("        INC A");
                            Emit("        MOVC A, @A+DPTR");
                            Emit("        MOV R0, A");
                            Emit("        PUSH 01H");  // push low byte
                            Emit("        PUSH 00H");  // push high byte
                            Emit("        POP 01H");
                            Emit("        POP 00H");
                        }
                    }
                    break;
                case OpCode.POPB:
                    {
                        var dst = instr.Operands[0];
                        if (dst.Type == OperandType.REGISTER)
                        {
                            int regNum = (int)dst.Value;
                            string offset = GetRegOffset(regNum);
                            Emit($"        ; POPB R{regNum} (8-bit, zero-extend)");
                            Emit("        POP ACC");
                            Emit("        PUSH 00H");
                            Emit("        PUSH 01H");
                            Emit($"        MOV R0, #{VR_BASE}");
                            Emit($"        MOV A, #{offset}");
                            Emit("        ADD A, R0");
                            Emit("        MOV R0, A");
                            Emit("        MOV @R0, A");
                            Emit("        POP 01H");
                            Emit("        POP 00H");
                        }
                    }
                    break;
                case OpCode.POPH:
                    {
                        var dst = instr.Operands[0];
                        if (dst.Type == OperandType.REGISTER)
                        {
                            int regNum = (int)dst.Value;
                            string offset = GetRegOffset(regNum);
                            Emit($"        ; POPW R{regNum} (16-bit, zero-extend)");
                            Emit("        POP ACC");
                            Emit("        MOV R1, A");   // low byte
                            Emit("        POP ACC");
                            Emit("        MOV R0, A");   // high byte
                            Emit("        PUSH 00H");
                            Emit($"        MOV R0, #{VR_BASE}");
                            Emit($"        MOV A, #{offset}");
                            Emit("        ADD A, R0");
                            Emit("        MOV R0, A");
                            Emit("        MOV @R0, R1");
                            Emit("        INC R0");
                            Emit("        MOV @R0, R0");
                            Emit("        POP 00H");
                        }
                    }
                    break;

                // 调试
                case OpCode.BREAK:
                    Emit("        ; BREAK - 8051断点");
                    Emit("        LCALL DEBUG_BREAK");
                    break;

                case OpCode.ZERO:
                    {
                        string off = GetRegOffset((int)instr.Operands[0].Value);
                        Emit($"        MOV R0, #{off}");
                        Emit($"        CLR A");
                        Emit($"        MOV @R0, A");
                        Emit($"        INC R0");
                        Emit($"        MOV @R0, A");
                        Emit($"        INC R0");
                        Emit($"        MOV @R0, A");
                        Emit($"        INC R0");
                        Emit($"        MOV @R0, A");
                    }
                    break;
                case OpCode.SHLV:
                    Emit("        LCALL SHL32");
                    break;
                case OpCode.SHRV:
                    Emit("        LCALL SHR32");
                    break;
                case OpCode.I2D:
                case OpCode.D2I:
                    Emit($"        LCALL FP_OP     ; {instr.Opcode}: {string.Join(", ", instr.Operands)}");
                    break;

                // 符号扩展/条件移动/循环移位 (v1.66.28+) — 软件库
                case OpCode.SEXTB: case OpCode.SEXTH:
                case OpCode.CMOVZ: case OpCode.CMOVNZ:
                case OpCode.ROL: case OpCode.ROR:
                    Emit($"        LCALL __{instr.Opcode.ToString().ToLower()}");
                    break;

                default:
                    Emit($"        ; UNIMPLEMENTED: {instr.Opcode.ToString()} {string.Join(", ", instr.Operands)}");
                    break;
            }
        }

        private void TranslateLoad(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];
            int regNum = (int)dst.Value;
            string offset = GetRegOffset(regNum);

            Emit($"        ; LOAD R{regNum}, src (32-bit)");
            Emit("        PUSH 00H");  // 保存 R0
            Emit("        PUSH 01H");  // 保存 R1

            // 计算目标地址：VR_BASE + offset
            Emit($"        MOV R0, #{VR_BASE}");
            Emit($"        MOV R1, #{offset}");
            Emit("        ADD A, R0");
            Emit("        MOV R0, A");

            if (src.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src);
                Emit($"        MOV @R0, #${value       & 0xFF:X2}");
                Emit("        INC R0");
                Emit($"        MOV @R0, #${(value >> 8) & 0xFF:X2}");
                Emit("        INC R0");
                Emit($"        MOV @R0, #${(value >> 16) & 0xFF:X2}");
                Emit("        INC R0");
                Emit($"        MOV @R0, #${(value >> 24) & 0xFF:X2}");
            }
            else if (src.Type == OperandType.MEMORY)
            {
                string addr = src.Value.ToString();
                Emit($"        MOV DPTR, #{addr}");
                Emit("        CLR A");
                Emit("        MOVC A, @A+DPTR");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC DPTR");
                Emit("        CLR A");
                Emit("        MOVC A, @A+DPTR");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC DPTR");
                Emit("        CLR A");
                Emit("        MOVC A, @A+DPTR");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC DPTR");
                Emit("        CLR A");
                Emit("        MOVC A, @A+DPTR");
                Emit("        MOV @R0, A");
            }
            else if (src.Type == OperandType.REGISTER)
            {
                int srcReg = (int)src.Value;
                string srcOffset = GetRegOffset(srcReg);
                Emit("        PUSH 02H");  // 保存 R2
                Emit("        MOV R2, #4");  // 循环计数
                Emit($"        MOV DPTR, #{VR_BASE}+{srcOffset}");
                Emit(".load_loop:");
                Emit("        MOVX A, @DPTR");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC DPTR");
                Emit("        DJNZ R2, .load_loop");
                Emit("        POP 02H");
            }
            else if (src.Type == OperandType.INDIRECT)
            {
                string ptr = src.Value.ToString();
                Emit("        ; Indirect load from pointer");
                // 需要从指针地址读取32位值
                Emit($"        MOV DPTR, {ptr}");
                Emit("        MOVX A, @DPTR");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC DPTR");
                Emit("        MOVX A, @DPTR");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC DPTR");
                Emit("        MOVX A, @DPTR");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC DPTR");
                Emit("        MOVX A, @DPTR");
                Emit("        MOV @R0, A");
            }

            Emit("        POP 01H");
            Emit("        POP 00H");
        }

        private void TranslateStore(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            Emit("        ; STORE");
            Emit("        PUSH 00H");
            Emit("        PUSH 01H");

            if (src.Type == OperandType.REGISTER)
            {
                int srcReg = (int)src.Value;
                string srcOffset = GetRegOffset(srcReg);

                if (dst.Type == OperandType.MEMORY)
                {
                    string addr = dst.Value.ToString();
                    Emit($"        MOV DPTR, #{addr}");
                    Emit($"        MOV R0, #{VR_BASE}+{srcOffset}");
                    Emit("        MOV A, @R0");
                    Emit("        MOVX @DPTR, A");
                    Emit("        INC R0");
                    Emit("        INC DPTR");
                    Emit("        MOV A, @R0");
                    Emit("        MOVX @DPTR, A");
                    Emit("        INC R0");
                    Emit("        INC DPTR");
                    Emit("        MOV A, @R0");
                    Emit("        MOVX @DPTR, A");
                    Emit("        INC R0");
                    Emit("        INC DPTR");
                    Emit("        MOV A, @R0");
                    Emit("        MOVX @DPTR, A");
                }
                else if (dst.Type == OperandType.INDIRECT)
                {
                    string ptr = dst.Value.ToString();
                    Emit($"        MOV DPTR, {ptr}");
                    Emit($"        MOV R0, #{VR_BASE}+{srcOffset}");
                    Emit("        MOV A, @R0");
                    Emit("        MOVX @DPTR, A");
                    Emit("        INC R0");
                    Emit("        INC DPTR");
                    Emit("        MOV A, @R0");
                    Emit("        MOVX @DPTR, A");
                    Emit("        INC R0");
                    Emit("        INC DPTR");
                    Emit("        MOV A, @R0");
                    Emit("        MOVX @DPTR, A");
                    Emit("        INC R0");
                    Emit("        INC DPTR");
                    Emit("        MOV A, @R0");
                    Emit("        MOVX @DPTR, A");
                }
            }
            else if (src.Type == OperandType.MEMORY)
            {
                // 从内存加载再存储到内存
                string srcAddr = src.Value.ToString();
                if (dst.Type == OperandType.MEMORY)
                {
                    string dstAddr = dst.Value.ToString();
                    Emit($"        MOV DPTR, #{dstAddr}");
                    Emit($"        MOV R0, #{srcAddr}");
                    Emit("        MOV A, @R0");
                    Emit("        MOVX @DPTR, A");
                    Emit("        INC DPTR");
                    Emit("        INC R0");
                    Emit("        MOV A, @R0");
                    Emit("        MOVX @DPTR, A");
                }
            }

            Emit("        POP 01H");
            Emit("        POP 00H");
        }

        private void TranslateAdd(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string dstOffset = GetRegOffset((int)dst.Value);
            string src1Offset = GetRegOffset((int)src1.Value);

            Emit("        ; 32-bit ADD (with carry chain)");
            Emit("        PUSH 00H");
            Emit("        PUSH 01H");
            Emit("        PUSH 02H");

            Emit($"        MOV R0, #{VR_BASE}+{dstOffset}");
            Emit($"        MOV R1, #{VR_BASE}+{src1Offset}");

            if (src2.Type == OperandType.REGISTER)
            {
                string src2Offset = GetRegOffset((int)src2.Value);
                Emit($"        MOV R2, #{VR_BASE}+{src2Offset}");
                Emit("        MOV A, @R1");
                Emit("        ADD A, @R2");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC R1");
                Emit("        INC R2");
                Emit("        MOV A, @R1");
                Emit("        ADDC A, @R2");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC R1");
                Emit("        INC R2");
                Emit("        MOV A, @R1");
                Emit("        ADDC A, @R2");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC R1");
                Emit("        INC R2");
                Emit("        MOV A, @R1");
                Emit("        ADDC A, @R2");
                Emit("        MOV @R0, A");
            }
            else if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit("        MOV A, @R1");
                Emit($"        ADD A, #${value       & 0xFF:X2}");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC R1");
                Emit("        MOV A, @R1");
                Emit($"        ADDC A, #${(value >> 8) & 0xFF:X2}");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC R1");
                Emit("        MOV A, @R1");
                Emit($"        ADDC A, #${(value >> 16) & 0xFF:X2}");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC R1");
                Emit("        MOV A, @R1");
                Emit($"        ADDC A, #${(value >> 24) & 0xFF:X2}");
                Emit("        MOV @R0, A");
            }

            Emit("        POP 02H");
            Emit("        POP 01H");
            Emit("        POP 00H");
        }

        private void TranslateSub(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string dstOffset = GetRegOffset((int)dst.Value);
            string src1Offset = GetRegOffset((int)src1.Value);

            Emit("        ; 32-bit SUB (with borrow chain)");
            Emit("        PUSH 00H");
            Emit("        PUSH 01H");
            Emit("        PUSH 02H");

            Emit("        CLR C");  // 清除借位

            Emit($"        MOV R0, #{VR_BASE}+{dstOffset}");
            Emit($"        MOV R1, #{VR_BASE}+{src1Offset}");

            if (src2.Type == OperandType.REGISTER)
            {
                string src2Offset = GetRegOffset((int)src2.Value);
                Emit($"        MOV R2, #{VR_BASE}+{src2Offset}");
                Emit("        MOV A, @R1");
                Emit("        SUBB A, @R2");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC R1");
                Emit("        INC R2");
                Emit("        MOV A, @R1");
                Emit("        SUBB A, @R2");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC R1");
                Emit("        INC R2");
                Emit("        MOV A, @R1");
                Emit("        SUBB A, @R2");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC R1");
                Emit("        INC R2");
                Emit("        MOV A, @R1");
                Emit("        SUBB A, @R2");
                Emit("        MOV @R0, A");
            }
            else if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit("        MOV A, @R1");
                Emit($"        SUBB A, #${value       & 0xFF:X2}");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC R1");
                Emit("        MOV A, @R1");
                Emit($"        SUBB A, #${(value >> 8) & 0xFF:X2}");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC R1");
                Emit("        MOV A, @R1");
                Emit($"        SUBB A, #${(value >> 16) & 0xFF:X2}");
                Emit("        MOV @R0, A");
                Emit("        INC R0");
                Emit("        INC R1");
                Emit("        MOV A, @R1");
                Emit($"        SUBB A, #${(value >> 24) & 0xFF:X2}");
                Emit("        MOV @R0, A");
            }

            Emit("        POP 02H");
            Emit("        POP 01H");
            Emit("        POP 00H");
        }

        private void TranslateMove(Instruction instr)
        {
            // v1.65.167+: 统一 MOVE — MEM/LABEL dest → Store, 其他 → Load
            if (instr.Operands[0].Type == OperandType.MEMORY ||
                instr.Operands[0].Type == OperandType.INDIRECT ||
                instr.Operands[0].Type == OperandType.LABEL)
            {
                TranslateStore(instr);
                return;
            }
            TranslateLoad(instr);
        }

        private void TranslateCmp(Instruction instr)
        {
            var src1 = instr.Operands[0];
            var src2 = instr.Operands[1];

            string src1Offset = GetRegOffset((int)src1.Value);

            Emit("        ; 32-bit CMP");
            Emit("        PUSH 00H");
            Emit("        PUSH 01H");
            Emit("        PUSH 02H");
            Emit("        PUSH 03H");
            Emit("        PUSH 04H");
            Emit("        CLR C");

            Emit($"        MOV R0, #{VR_BASE}+{src1Offset}");

            if (src2.Type == OperandType.REGISTER)
            {
                string src2Offset = GetRegOffset((int)src2.Value);
                Emit($"        MOV R1, #{VR_BASE}+{src2Offset}");
                // 从高位开始比较，用 R3/R4 做临时地址指针
                Emit("        MOV R2, #3");
                Emit(".cmp_loop:");
                Emit("        MOV A, R0");
                Emit("        ADD A, R2");
                Emit("        MOV R3, A");
                Emit("        MOV A, R1");
                Emit("        ADD A, R2");
                Emit("        MOV R4, A");
                Emit("        MOV A, @R3");
                Emit("        SUBB A, @R4");
                Emit("        JNZ .cmp_done");
                Emit("        DEC R2");
                Emit("        MOV A, R2");
                Emit("        ADD A, #1");
                Emit("        JNZ .cmp_loop");
                Emit(".cmp_done:");
            }
            else if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                // 将立即数加载到内存临时变量 (20H-23H) 然后比较
                Emit($"        MOV 20H, #${value       & 0xFF:X2}");
                Emit($"        MOV 21H, #${(value >> 8) & 0xFF:X2}");
                Emit($"        MOV 22H, #${(value >> 16) & 0xFF:X2}");
                Emit($"        MOV 23H, #${(value >> 24) & 0xFF:X2}");
                Emit("        MOV R1, #20H");
                // 用 R3/R4 做临时指针
                Emit("        MOV R2, #3");
                Emit(".cmp_imm_loop:");
                Emit("        MOV A, R0");
                Emit("        ADD A, R2");
                Emit("        MOV R3, A");
                Emit("        MOV A, R1");
                Emit("        ADD A, R2");
                Emit("        MOV R4, A");
                Emit("        MOV A, @R3");
                Emit("        SUBB A, @R4");
                Emit("        JNZ .cmp_imm_done");
                Emit("        DEC R2");
                Emit("        MOV A, R2");
                Emit("        ADD A, #1");
                Emit("        JNZ .cmp_imm_loop");
                Emit(".cmp_imm_done:");
            }

            Emit("        POP 04H");
            Emit("        POP 03H");
            Emit("        POP 02H");
            Emit("        POP 01H");
            Emit("        POP 00H");
        }

        protected override string MapRegister(int regNum)
        {
            return REGISTER_MAP.TryGetValue(regNum, out string reg) ? reg : $"R{regNum}";
        }
    }
}
